func (this *Poloniex) ParseOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	// spot:
	//
	//     [
	//         [
	//             "22814.01",
	//             "22937.42",
	//             "22832.57",
	//             "22937.42",
	//             "3916.58764051",
	//             "0.171199",
	//             "2982.64647063",
	//             "0.130295",
	//             33,
	//             0,
	//             "22877.449915304470460711",
	//             "MINUTE_5",
	//             1659664800000,
	//             1659665099999
	//         ]
	//     ]
	//
	// contract:
	//
	//           [
	//             "84207.02",
	//             "84320.85",
	//             "84207.02",
	//             "84253.83",
	//             "3707.5395",
	//             "44",
	//             "14",
	//             "1740770040000",
	//             "1740770099999",
	//           ],
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var ohlcvLength int = GetArrayLength(ohlcv)
	var isContract bool = (ohlcvLength == 9)
	if isContract {
		return []any{this.SafeInteger(ohlcv, 7), this.SafeNumber(ohlcv, 2), this.SafeNumber(ohlcv, 1), this.SafeNumber(ohlcv, 0), this.SafeNumber(ohlcv, 3), this.SafeNumber(ohlcv, 5)}
	}
	return []any{this.SafeInteger(ohlcv, 12), this.SafeNumber(ohlcv, 2), this.SafeNumber(ohlcv, 1), this.SafeNumber(ohlcv, 0), this.SafeNumber(ohlcv, 3), this.SafeNumber(ohlcv, 5)}
}

/**
 * @method
 * @name poloniex#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://api-docs.poloniex.com/spot/api/public/market-data#candles
 * @see https://api-docs.poloniex.com/v3/futures/api/market/get-kline-data
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Poloniex) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Poloniex) fetchOHLCVBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	PanicOnError((<-this.LoadMarketsAsync()))
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchOHLCV", "paginate", false)
	if paginate {

		var retRes69119 []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallDeterministicAsync("fetchOHLCV", symbol, since, limit, timeframe, paramsPaginate, 500))))
		if retRes69119 == nil {
			ch <- nil
		} else {
			ch <- retRes69119
		}
		return nil
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol":   market["id"],
		"interval": this.SafeString(this.Timeframes, timeframe, timeframe),
	}
	var keyStart string = "sTime"
	if market["spot"] == true {
		keyStart = "startTime"
	}
	var keyEnd string = "eTime"
	if market["spot"] == true {
		keyEnd = "endTime"
	}
	if since != nil {
		request[keyStart] = since
	}
	if limit != nil {
		// limit should in between 100 and 500
		request["limit"] = limit
	}
	requestUntil, paramsUntil := this.HandleUntilOption(keyEnd, request, paramsPaginate)
	if market["contract"] == true {

		var responseRaw map[string]any = (<-this.SwapPublicGetV3MarketCandles(this.Extend(requestUntil, paramsUntil))).Checked()
		//
		//     {
		//         code: "200",
		//         msg: "Success",
		//         data: [
		//           [
		//             "84207.02",
		//             "84320.85",
		//             "84207.02",
		//             "84253.83",
		//             "3707.5395",
		//             "44",
		//             "14",
		//             "1740770040000",
		//             "1740770099999",
		//           ],
		//
		var data []any = SafeListTyped(responseRaw, "data")

		ch <- this.ParseOHLCVs(data, market, timeframe, since, limit)
		return nil
	}

	response := (<-this.PublicGetMarketsSymbolCandles(this.Extend(requestUntil, paramsUntil))).Raw
	PanicOnError(response)
	//
	//     [
	//         [
	//             "22814.01",
	//             "22937.42",
	//             "22832.57",
	//             "22937.42",
	//             "3916.58764051",
	//             "0.171199",
	//             "2982.64647063",
	//             "0.130295",
	//             33,
	//             0,
	//             "22877.449915304470460711",
	//             "MINUTE_5",
	//             1659664800000,
	//             1659665099999
	//         ]
	//     ]
	//
	var candles []any = []any{}
	if IsArray(response) {
		candles = ArrayTyped(response)
	}

	ch <- this.ParseOHLCVs(candles, market, timeframe, since, limit)
	return nil
}
func (this *Poloniex) LoadMarketsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.loadMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Poloniex) loadMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var reload bool = GetArgBool(optionalArgs, 0, false)
	_ = reload
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	markets := (<-this.Exchange.LoadMarketsAsync(reload, params))
	PanicOnError(markets)
	var currenciesByNumericId any = this.SafeDict(this.Options, "currenciesByNumericId")
	if ((currenciesByNumericId == nil)) || (reload == true) {
		this.Options.Store("currenciesByNumericId", this.IndexBy(this.Currencies, "numericId"))
	}

	ch <- markets
	return nil
}

