func (this *Poloniex) ParseMarket(market any) any {
	if InOp(market, "ctType") {
		return this.ParseSwapMarket(market)
	} else {
		return this.ParseSpotMarket(market)
	}
}
func (this *Poloniex) ParseSpotMarket(market any) any {
	var id *string = this.SafeString(market, "symbol")
	var baseId *string = this.SafeString(market, "baseCurrencyName")
	var quoteId *string = this.SafeString(market, "quoteCurrencyName")
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	if (base == nil) || (quote == nil) {
		return nil
	}
	var state *string = this.SafeString(market, "state")
	var active bool = (state != nil && *state == "NORMAL")
	var symbolTradeLimit map[string]any = SafeMapTyped(market, "symbolTradeLimit")
	// these are known defaults
	return this.SafeMarketStructure(map[string]any{
		"id":             id,
		"symbol":         *base + "/" + *quote,
		"base":           base,
		"quote":          quote,
		"settle":         nil,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       nil,
		"type":           "spot",
		"spot":           true,
		"margin":         false,
		"swap":           false,
		"future":         false,
		"option":         false,
		"active":         active,
		"contract":       false,
		"linear":         nil,
		"inverse":        nil,
		"contractSize":   nil,
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(symbolTradeLimit, "quantityScale"))),
			"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(symbolTradeLimit, "priceScale"))),
		},
		"limits": map[string]any{
			"amount": map[string]any{
				"min": this.SafeNumber(symbolTradeLimit, "minQuantity"),
				"max": nil,
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": this.SafeNumber(symbolTradeLimit, "minAmount"),
				"max": nil,
			},
		},
		"created": this.SafeInteger(market, "tradableStartTime"),
		"info":    market,
	})
}
func (this *Poloniex) ParseSwapMarket(market any) any {
	//
	//            {
	//                "symbol": "BNB_USDT_PERP",
	//                "bAsset": ".PBNBUSDT",
	//                "bCcy": "BNB",
	//                "qCcy": "USDT",
	//                "visibleStartTime": "1620390600000",
	//                "tradableStartTime": "1620390600000",
	//                "sCcy": "USDT",
	//                "tSz": "0.001",
	//                "pxScale": "0.001,0.01,0.1,1,10",
	//                "lotSz": "1",
	//                "minSz": "1",
	//                "ctVal": "0.1",
	//                "status": "OPEN",
	//                "oDate": "1620287590000",
	//                "maxPx": "1000000",
	//                "minPx": "0.001",
	//                "maxQty": "1000000",
	//                "minQty": "1",
	//                "maxLever": "50",
	//                "lever": "10",
	//                "ctType": "LINEAR",
	//                "alias": "",
	//                "iM": "0.02",
	//                "mM": "0.0115",
	//                "mR": "2000",
	//                "buyLmt": "",
	//                "sellLmt": "",
	//                "ordPxRange": "0.05",
	//                "marketMaxQty": "2800",
	//                "limitMaxQty": "1000000"
	//            },
	//
	var id *string = this.SafeString(market, "symbol")
	var baseId *string = this.SafeString(market, "bCcy")
	var quoteId *string = this.SafeString(market, "qCcy")
	var settleId *string = this.SafeString(market, "sCcy")
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	if (base == nil) || (quote == nil) {
		return nil
	}
	var settle *string = this.SafeCurrencyCode(settleId)
	var status *string = this.SafeString(market, "status")
	var active bool = (status != nil && *status == "OPEN")
	var linear bool = (this.SafeString(market, "ctType") != nil && *this.SafeString(market, "ctType") == "LINEAR")
	var symbol any = *base + "/" + *quote
	if linear {
		symbol = Add(symbol, Add(":", settle))
	} else {
		// actually, exchange does not have any inverse future now
		symbol = Add(symbol, ":"+*base)
	}
	var alias *string = this.SafeString(market, "alias")
	var typeVar string = "swap"
	if alias != nil {
		typeVar = "future"
	}
	var marketType string = "swap"
	if typeVar == "future" {
		marketType = "future"
	}
	return this.SafeMarketStructure(map[string]any{
		"id":             id,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       settleId,
		"type":           marketType,
		"spot":           false,
		"margin":         false,
		"swap":           (typeVar == "swap"),
		"future":         (typeVar == "future"),
		"option":         false,
		"active":         active,
		"contract":       true,
		"linear":         linear,
		"inverse":        !linear,
		"contractSize":   this.SafeNumber(market, "ctVal"),
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"taker":          this.SafeNumber(market, "tFee"),
		"maker":          this.SafeNumber(market, "mFee"),
		"precision": map[string]any{
			"amount": this.SafeNumber(market, "lotSz"),
			"price":  this.SafeNumber(market, "tSz"),
		},
		"limits": map[string]any{
			"amount": map[string]any{
				"min": this.SafeNumber(market, "minSz"),
				"max": this.SafeNumber(market, "limitMaxQty"),
			},
			"price": map[string]any{
				"min": this.SafeNumber(market, "minPx"),
				"max": this.SafeNumber(market, "maxPx"),
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
			"leverage": map[string]any{
				"max": this.SafeNumber(market, "maxLever"),
				"min": nil,
			},
		},
		"created": this.SafeInteger(market, "oDate"),
		"info":    market,
	})
}

