/**
 * @method
 * @name poloniex#fetchDepositAddress
 * @description fetch the deposit address for a currency associated with this account
 * @see https://api-docs.poloniex.com/spot/api/private/wallet#deposit-addresses
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Poloniex) FetchDepositAddressAsync(code string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Poloniex) fetchDepositAddressBody(ch chan any, code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	PanicOnError((<-this.LoadMarketsAsync()))
	requestextraParamscurrencynetworkEntryVariable := this.PrepareRequestForDepositAddress(code, params)
	request := GetValue(requestextraParamscurrencynetworkEntryVariable, 0)
	extraParams := GetValue(requestextraParamscurrencynetworkEntryVariable, 1)
	currency := GetValue(requestextraParamscurrencynetworkEntryVariable, 2)
	networkEntry := GetValue(requestextraParamscurrencynetworkEntryVariable, 3)
	var paramsValue any = extraParams

	var response map[string]any = (<-this.PrivateGetWalletsAddresses(this.Extend(request, paramsValue))).Checked()
	//
	//     {
	//         "USDTTRON" : "Txxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxp"
	//     }
	//
	var keys []string = nil
	if response != nil {
		keys = make([]string, 0, len(response))
		for objectKey := range response {
			keys = append(keys, objectKey)
		}
	}
	var length int = len(keys)
	if length < 1 {
		panic(ExchangeError(this.Id + " fetchDepositAddress() returned an empty response, you might need to try \"createDepositAddress\" at first and then use \"fetchDepositAddress\""))
	}

	ch <- this.ParseDepositAddressSpecial(response, currency, networkEntry)
	return nil
}
func (this *Poloniex) PrepareRequestForDepositAddress(code string, optionalArgs ...any) any {
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if !(InOp(this.Currencies, code)) {
		panic(BadSymbol(this.Id + " fetchDepositAddress(): can not recognize " + code + " currency, you might try using unified currency-code and add provide specific \"network\" parameter, like: fetchDepositAddress(\"USDT\", { \"network\": \"TRC20\" })"))
	}
	var currency map[string]any = this.Currency(code)
	var networkCode any = nil
	var query any = nil
	var networkCodequeryVariable []any = this.HandleNetworkCodeAndParams(params)
	networkCode = GetValue(networkCodequeryVariable, 0)
	query = GetValue(networkCodequeryVariable, 1)
	if networkCode == nil {
		panic(ArgumentsRequired(this.Id + " fetchDepositAddress requires a network parameter for " + code + "."))
	}
	var exchangeNetworkId any = nil
	networkCode = DerefScalar(this.NetworkIdToCode(networkCode, code))
	var networkEntry any = func() any {
		if networkCode == nil {
			return nil
		}
		return this.SafeDict(currency["networks"], networkCode)
	}()
	if networkEntry != nil {
		exchangeNetworkId = GetValue(networkEntry, "id")
	} else {
		exchangeNetworkId = networkCode
	}
	var request map[string]any = map[string]any{
		"currency": exchangeNetworkId,
	}
	return []any{request, query, currency, networkEntry}
}
func (this *Poloniex) ParseDepositAddressSpecial(response any, currency any, networkEntry any) any {
	var address *string = this.SafeString(response, "address")
	if address == nil {
		address = this.SafeString(response, GetValue(networkEntry, "id"))
	}
	var tag *string = nil
	this.CheckAddress(address)
	if !IsEqual(networkEntry, nil) {
		var depositAddress *string = this.SafeString(GetValue(networkEntry, "info"), "depositAddress")
		if depositAddress != nil {
			tag = address
			address = depositAddress
		}
	}
	return map[string]any{
		"info":     response,
		"currency": GetValue(currency, "code"),
		"network":  this.SafeString(networkEntry, "network"),
		"address":  address,
		"tag":      tag,
	}
}

