/**
 * @method
 * @name poloniex#fetchDepositWithdrawFees
 * @description fetch deposit and withdraw fees
 * @see https://api-docs.poloniex.com/spot/api/public/reference-data#currency-information
 * @param {string[]|undefined} codes list of unified currency codes
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [fees structures]{@link https://docs.ccxt.com/?id=fee-structure}
 */
func (this *Poloniex) FetchDepositWithdrawFeesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchDepositWithdrawFeesBody(ch, optionalArgs...)
	return ch
}
func (this *Poloniex) fetchDepositWithdrawFeesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	PanicOnError((<-this.LoadMarketsAsync()))

	response := (<-this.PublicGetCurrencies(this.Extend(params, map[string]any{
		"includeMultiChainCurrencies": true,
	}))).Raw
	PanicOnError(response)
	//
	//     [
	//         {
	//             "1CR": {
	//                 "id": 1,
	//                 "name": "1CRedit",
	//                 "description": "BTC Clone",
	//                 "type": "address",
	//                 "withdrawalFee": "0.01000000",
	//                 "minConf": 10000,
	//                 "depositAddress": null,
	//                 "blockchain": "1CR",
	//                 "delisted": false,
	//                 "tradingState": "NORMAL",
	//                 "walletState": "DISABLED",
	//                 "parentChain": null,
	//                 "isMultiChain": false,
	//                 "isChildChain": false,
	//                 "childChains": []
	//             }
	//         }
	//     ]
	//
	var data map[string]any = map[string]any{}
	var entries []any = []any{}
	if IsArray(response) {
		entries = ArrayTyped(response)
	}
	for i := 0; i < len(entries); i++ {
		var entry any = func() any {
			if i >= 0 && i < len(entries) {
				return DerefScalar(entries[i])
			}
			return nil
		}()
		var currencies []string = ObjectKeys(entry)
		var currencyId *string = this.SafeString(currencies, 0)
		AddElementToObject(data, currencyId, GetValue(entry, currencyId))
	}

	ch <- this.ParseDepositWithdrawFees(data, codes)
	return nil
}
func (this *Poloniex) ParseDepositWithdrawFees(response any, optionalArgs ...any) any {
	//
	//         {
	//             "1CR": {
	//                 "id": 1,
	//                 "name": "1CRedit",
	//                 "description": "BTC Clone",
	//                 "type": "address",
	//                 "withdrawalFee": "0.01000000",
	//                 "minConf": 10000,
	//                 "depositAddress": null,
	//                 "blockchain": "1CR",
	//                 "delisted": false,
	//                 "tradingState": "NORMAL",
	//                 "walletState": "DISABLED",
	//                 "parentChain": null,
	//                 "isMultiChain": false,
	//                 "isChildChain": false,
	//                 "childChains": []
	//             },
	//         }
	//
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var currencyIdKey *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = currencyIdKey
	var depositWithdrawFees map[string]any = map[string]any{}
	var codesValue any = this.MarketCodes(codes)
	var responseKeys []string = ObjectKeys(response)
	for i := 0; i < len(responseKeys); i++ {
		var currencyId string = responseKeys[i]
		var code *string = this.SafeCurrencyCode(currencyId)
		var feeInfo any = GetValue(response, currencyId)
		if (code != nil) && ((IsEqual(codesValue, nil)) || (this.InArray(code, codesValue))) {
			var currency map[string]any = this.Currency(code)
			AddElementToObject(depositWithdrawFees, code, this.ParseDepositWithdrawFee(feeInfo, currency))
			var childChains any = this.SafeValue(feeInfo, "childChains")
			var chainsLength int = GetArrayLength(childChains)
			if chainsLength > 0 {
				for j := 0; j < GetArrayLength(childChains); j++ {
					var networkId any = GetValue(childChains, j)
					networkId = Replace(networkId, code, "")
					var networkCode *string = this.NetworkIdToCode(networkId, this.SafeString(currency, "code"))
					var networkInfo map[string]any = SafeMapTyped(response, networkId)
					var networkObject map[string]any = map[string]any{}
					var withdrawFee *float64 = this.SafeNumber(networkInfo, "withdrawalFee")
					if networkCode != nil {
						networkObject[*networkCode] = map[string]any{
							"withdraw": map[string]any{
								"fee": withdrawFee,
								"percentage": func() any {
									if withdrawFee != nil {
										return false
									}
									return nil
								}(),
							},
							"deposit": map[string]any{
								"fee":        nil,
								"percentage": nil,
							},
						}
					}
					AddElementToObject(GetValue(depositWithdrawFees, code), "networks", this.Extend(GetValue(func() any {
						if code == nil {
							return nil
						}
						return depositWithdrawFees[*code]
					}(), "networks"), networkObject))
				}
			}
		}
	}
	return depositWithdrawFees
}
func (this *Poloniex) ParseDepositWithdrawFee(fee any, optionalArgs ...any) any {
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var depositWithdrawFee any = this.DepositWithdrawFee(map[string]any{})
	var currencyCode *string = this.SafeString(currency, "code")
	AddElementToObject(GetValue(depositWithdrawFee, "info"), currencyCode, fee)
	var networkId *string = this.SafeString(fee, "blockchain")
	var withdrawFee *float64 = this.SafeNumber(fee, "withdrawalFee")
	var withdrawResult map[string]any = map[string]any{
		"fee": withdrawFee,
		"percentage": func() any {
			if withdrawFee != nil {
				return false
			}
			return nil
		}(),
	}
	var depositResult map[string]any = map[string]any{
		"fee":        nil,
		"percentage": nil,
	}
	AddElementToObject(depositWithdrawFee, "withdraw", withdrawResult)
	AddElementToObject(depositWithdrawFee, "deposit", depositResult)
	var networkCode *string = this.NetworkIdToCode(networkId, this.SafeString(currency, "code"))
	if networkCode != nil {
		AddElementToObject(GetValue(depositWithdrawFee, "networks"), networkCode, map[string]any{
			"withdraw": withdrawResult,
			"deposit":  depositResult,
		})
	}
	return depositWithdrawFee
}

