func (this *Poloniex) ParseTransactionStatus(status any) *string {
	var statuses map[string]any = map[string]any{
		"COMPLETE":          "ok",
		"COMPLETED":         "ok",
		"AWAITING APPROVAL": "pending",
		"AWAITING_APPROVAL": "pending",
		"PENDING":           "pending",
		"PROCESSING":        "pending",
		"COMPLETE ERROR":    "failed",
		"COMPLETE_ERROR":    "failed",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Poloniex) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// deposits
	//
	//     {
	//         "txid": "f49d489616911db44b740612d19464521179c76ebe9021af85b6de1e2f8d68cd",
	//         "amount": "49798.01987021",
	//         "status": "COMPLETE",
	//         "address": "DJVJZ58tJC8UeUv9Tqcdtn6uhWobouxFLT",
	//         "currency": "DOGE",
	//         "timestamp": 1524321838,
	//         "confirmations": 3371,
	//         "depositNumber": 134587098
	//     }
	//
	// withdrawals
	//
	//     {
	//         "withdrawalRequestsId": 7397527,
	//         "currency": "ETC",
	//         "address": "0x26419a62055af459d2cd69bb7392f5100b75e304",
	//         "amount": "13.19951600",
	//         "fee": "0.01000000",
	//         "timestamp": 1506010932,
	//         "status": "COMPLETED",
	//         "txid": "343346392f82ac16e8c2604f2a604b7b2382d0e9d8030f673821f8de4b5f5bk",
	//         "ipAddress": "1.2.3.4",
	//         "paymentID": null
	//     }
	//
	// withdraw
	//
	//     {
	//         "withdrawalRequestsId": 33485231
	//     }
	//
	// if it's being parsed from "withdraw()" method, get the original response
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var transactionValue any = transaction
	if InOp(transaction, "withdrawNetworkEntry") {
		transactionValue = GetValue(transaction, "response")
	}
	var timestamp *int64 = this.SafeTimestamp(transactionValue, "timestamp")
	var currencyId *string = this.SafeString(transactionValue, "currency")
	var code *string = this.SafeCurrencyCode(currencyId)
	var status any = DerefScalar(this.SafeString(transactionValue, "status", "pending"))
	status = this.ParseTransactionStatus(status)
	var txid *string = this.SafeString(transactionValue, "txid")
	var typeVar string = "deposit"
	if InOp(transactionValue, "withdrawalRequestsId") {
		typeVar = "withdrawal"
	}
	var id *string = this.SafeString2(transactionValue, "withdrawalRequestsId", "depositNumber")
	var address *string = this.SafeString(transactionValue, "address")
	var tag *string = this.SafeString(transactionValue, "paymentID")
	var amountString *string = this.SafeString(transactionValue, "amount")
	var feeCostString *string = this.SafeString(transactionValue, "fee")
	if typeVar == "withdrawal" {
		amountString = Precise.StringSub(amountString, feeCostString)
	}
	return map[string]any{
		"info":        transactionValue,
		"id":          id,
		"currency":    code,
		"amount":      this.ParseNumber(amountString),
		"network":     nil,
		"address":     address,
		"addressTo":   nil,
		"addressFrom": nil,
		"tag":         tag,
		"tagTo":       nil,
		"tagFrom":     nil,
		"status":      status,
		"type":        typeVar,
		"updated":     nil,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"comment":     nil,
		"internal":    nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     this.ParseNumber(feeCostString),
			"rate":     nil,
		},
	}
}

/**
 * @method
 * @name poloniex#setLeverage
 * @description set the level of leverage for a market
 * @see https://api-docs.poloniex.com/v3/futures/api/positions/set-leverage
 * @param {int} leverage the rate of leverage
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.marginMode] 'cross' or 'isolated'
 * @returns {object} response from the exchange
 */
func (this *Poloniex) SetLeverageAsync(leverage int64, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.setLeverageBody(ch, leverage, optionalArgs...)
	return ch
}
func (this *Poloniex) setLeverageBody(ch chan any, leverage int64, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " setLeverage() requires a symbol argument"))
	}

	PanicOnError((<-this.LoadMarketsAsync()))
	var market map[string]any = this.Market(symbol)
	marginMode, paramsMarginMode := this.HandleMarginModeAndParams("setLeverage", params)
	if IsEqual(marginMode, nil) {
		panic(ArgumentsRequired(this.Id + " setLeverage() requires a marginMode parameter \"cross\" or \"isolated\""))
	}
	var hedgedparamsHedgedVariable []any = this.HandleParamBool(paramsMarginMode, "hedged", false)
	hedged := GetValue(hedgedparamsHedgedVariable, 0)
	var paramsHedged map[string]any = MapTyped(hedgedparamsHedgedVariable[1])
	if hedged == true {
		if _, ok := paramsHedged["posSide"]; !ok {
			panic(ArgumentsRequired(this.Id + " setLeverage() requires a posSide parameter for hedged mode: \"LONG\" or \"SHORT\""))
		}
	}
	var request map[string]any = map[string]any{
		"lever":   leverage,
		"mgnMode": ToUpper(marginMode),
		"symbol":  market["id"],
	}

	response := (<-this.SwapPrivatePostV3PositionLeverage(this.Extend(request, paramsHedged))).Raw
	PanicOnError(response)

	ch <- response
	return nil
}

/**
 * @method
 * @name poloniex#fetchLeverage
 * @description fetch the set leverage for a market
 * @see https://api-docs.poloniex.com/v3/futures/api/positions/get-leverages
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [leverage structure]{@link https://docs.ccxt.com/?id=leverage-structure}
 */
func (this *Poloniex) FetchLeverageAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchLeverageBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Poloniex) fetchLeverageBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	PanicOnError((<-this.LoadMarketsAsync()))
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	marginMode, paramsMarginMode := this.HandleMarginModeAndParams("fetchLeverage", params)
	if IsEqual(marginMode, nil) {
		panic(ArgumentsRequired(this.Id + " fetchLeverage() requires a marginMode parameter \"cross\" or \"isolated\""))
	}
	request["mgnMode"] = ToUpper(marginMode)

	var response map[string]any = (<-this.SwapPrivateGetV3PositionLeverages(this.Extend(request, paramsMarginMode))).Checked()

	//
	//  for one-way mode:
	//
	//    {
	//        "code": "200",
	//        "msg": "",
	//        "data": [
	//            {
	//                "symbol": "BTC_USDT_PERP",
	//                "lever": "10",
	//                "mgnMode": "CROSS",
	//                "posSide": "BOTH"
	//            }
	//        ]
	//    }
	//
	//  for hedge:
	//
	//    {
	//        "code": "200",
	//        "msg": "",
	//        "data": [
	//            {
	//                "symbol": "BTC_USDT_PERP",
	//                "lever": "20",
	//                "mgnMode": "CROSS",
	//                "posSide": "SHORT"
	//            },
	//            {
	//                "symbol": "BTC_USDT_PERP",
	//                "lever": "20",
	//                "mgnMode": "CROSS",
	//                "posSide": "LONG"
	//            }
	//        ]
	//    }
	//
	ch <- this.ParseLeverage(response, market)
	return nil
}
func (this *Poloniex) ParseLeverage(leverage any, optionalArgs ...any) any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var shortLeverage *int64 = nil
	var longLeverage *int64 = nil
	var marketId any = nil
	var marginMode *string = nil
	var data []any = SafeListTyped(leverage, "data")
	for i := 0; i < len(data); i++ {
		var entry map[string]any = SafeMapTyped(data, i)
		marketId = DerefScalar(this.SafeString(entry, "symbol"))
		// mgnMode arrives upper case; parseOrder and parsePosition read the
		// same field with safeStringLower
		marginMode = this.SafeStringLower(entry, "mgnMode")
		var lever *int64 = this.SafeInteger(entry, "lever")
		var posSide *string = this.SafeString(entry, "posSide")
		if posSide != nil && *posSide == "LONG" {
			longLeverage = lever
		} else if posSide != nil && *posSide == "SHORT" {
			shortLeverage = lever
		} else {
			longLeverage = lever
			shortLeverage = lever
		}
	}
	return map[string]any{
		"info":          leverage,
		"symbol":        this.SafeSymbol(marketId, market),
		"marginMode":    marginMode,
		"longLeverage":  longLeverage,
		"shortLeverage": shortLeverage,
	}
}

