func (this *Poloniex) Nonce() any {
	return this.Milliseconds()
}
func (this *Poloniex) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	var body *string = GetArgStringPtr(optionalArgs, 4, nil)
	_ = body
	var url any = GetValue(GetValue(this.Urls, "api"), "spot")
	if this.InArray(api, []any{"swapPublic", "swapPrivate"}) {
		url = GetValue(GetValue(this.Urls, "api"), "swap")
	}
	if (method == "GET") && (InOp(params, "symbol")) {
		AddElementToObject(params, "symbol", this.EncodeURIComponent(GetValue(params, "symbol"))) // handle symbols like 索拉拉/USDT'
	}
	var query any = this.Omit(params, this.ExtractParams(path))
	var implodedPath string = this.ImplodeParams(path, params)
	var bodyJson any = nil
	var signedHeaders any = nil
	if ((api == "public")) || ((api == "swapPublic")) {
		url = Add(url, "/"+implodedPath)
		if len(ObjectKeys(query)) > 0 {
			url = Add(url, "?"+this.Urlencode(query))
		}
	} else {
		this.CheckRequiredCredentials()
		var timestamp string = ToString(this.Nonce())
		var auth any = method + "\n" // eslint-disable-line quotes
		url = Add(url, "/"+implodedPath)
		auth = Add(auth, "/"+implodedPath)
		if (method == "POST") || (method == "PUT") || (method == "DELETE") {
			auth = Add(auth, "\n") // eslint-disable-line quotes
			if len(ObjectKeys(query)) > 0 {
				bodyJson = this.Json(query)
				auth = Add(auth, Add(Add("requestBody=", bodyJson), "&"))
			}
			auth = Add(auth, "signTimestamp="+timestamp)
		} else {
			var sortedQuery map[string]any = this.Extend(map[string]any{
				"signTimestamp": timestamp,
			}, query)
			sortedQuery = this.Keysort(sortedQuery)
			auth = Add(auth, "\n"+this.Urlencode(sortedQuery)) // eslint-disable-line quotes
			if len(ObjectKeys(query)) > 0 {
				url = Add(url, "?"+this.Urlencode(query))
			}
		}
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha256, "base64")
		signedHeaders = map[string]any{
			"Content-Type":  "application/json",
			"key":           this.ApiKey,
			"signTimestamp": timestamp,
			"signature":     signature,
		}
	}
	var bodyResolved any = func() any {
		if bodyJson == nil {
			return body
		}
		return bodyJson
	}()
	var headersResolved any = func() any {
		if signedHeaders == nil {
			return headers
		}
		return signedHeaders
	}()
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResolved,
		"headers": headersResolved,
	}
}
func (this *Poloniex) HandleErrors(code any, reason any, url any, method any, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil
	}
	//
	//     {
	//         "code" : 21709,
	//         "message" : "Low available balance"
	//     }
	//
	var responseCode *string = this.SafeString(response, "code")
	if (responseCode != nil) && (responseCode == nil || *responseCode != "200") {
		var message *string = this.SafeString2(response, "message", "msg")
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], responseCode, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

